"""Prepare imagegen CLI edit prompts; no requests or credentials in this file."""
from pathlib import Path
import json
REC=Path(__file__).resolve().parent
common='''Use case: style-transfer. Production sprite for a premium casual honeybee town building game.
Image 1 is the EDIT TARGET and determines exact subject orientation, silhouette occupancy and center. Image 2 (bee builder) and Image 3 (S03 game page) are STYLE REFERENCES ONLY. Never include the bee or buildings in this sprite.
Redraw the target as fresh polished cartoon game artwork matching the bee builder: rounded sculpted forms, clean warm golden-brown outlines, softly shaded bevels, light coming from upper left, coherent honey-gold palette. Keep its canvas-center pivot, original pose, horizontal orientation and subject footprint. The sprite will be downsampled to the original small target canvas. Keep the entire sprite visible with a small transparent safe margin. No text, digits, branding, watermark, backdrop, floor or background shadow.
Output one isolated sprite with genuine transparent alpha background. Do not render a checkerboard, black rectangle or white rectangle. No realistic photographic or wispy noise textures.
'''
specs={
'hammer':'''Target delivery133x105. A horizontal wooden-handled IRON HAMMER. Handle points LEFT, hammer head stands VERTICAL on RIGHT. Do NOT rotate or mirror. Match Image1: left grip tip around x3%, shaft extends from x3% to58% at y50%; head occupies right45%, x55%-97%, y3%-97%. Warm brown wooden handle, LARGE silver gray rounded iron head with a small honey yellow band, golden brown outline. Iron must be recognizable silver, not a wooden mallet. The shaft ends inside the center of the head. Keep the original short chunky silhouette; no decorative tail.''',
'saw':'''Target delivery180x68. A horizontal HANDSAW, blade on LEFT, closed-loop warm brown wooden handle on RIGHT. Serrated cutting teeth MUST point UP along the TOP edge, flat gently sloping blade edge on bottom exactly as Image1. Do not mirror or rotate. Blade x3%-80%, handle x72%-97%; preserve their original height/center. Pale steel blue blade with broad upper-left highlights, warm honey-brown rounded handle with a clean transparent finger hole and golden brown outline. Chunky, friendly and polished. No lettering on blade.''',
'smoke':'''Target delivery169x160. ONE centered rounded CARTOON DUST CLOUD, puffy volume occupying approximately94% width and94% height with transparent padding, similar outer occupancy to Image1. Use5-7 large clean rounded lobes. Cream ivory body, a warm beige/tan shadow along bottom, thin warm golden brown contour about1.5px at target size. Style matches a cartoon builder bee. Clean inflated sculpted forms, upper-left creamy highlight; not a photo, no realistic smoke noise or vapor. No face, particles, sparkles, tools, ground or explosion. This cloud is tall/round, not flat.''',
'puff':'''Target delivery169x160. ONE centered CARTOON DUST PUFF for construction. Similar overall footprint and center to Image1, but deliberately DIFFERENT from the round smoke: broader/flatter lower body with an extra round lobe protruding at upper right,6-8 distinct clean inflated lobes. Cream ivory body, warm beige/tan bottom shadow, thin warm golden brown contour about1.5px at target size. Upper-left soft highlight, simple readable forms; no photographic smoke texture, vapor, noise, face, tools, glitter or ground. Modestly wider than tall, yet occupies at least85% of canvas height.''',
'ray':'''Target delivery156x142. ONE transparent cartoon construction-completion LIGHT BURST. Centered bright warm-white small center at exact canvas midpoint, a tiny honey yellow hexagon highlight at center. Exactly10 broad tapered honey-gold to warm-white rays radiate outward, evenly spaced, with softly fading tips and gaps fully transparent. Balanced radial composition, all rays complete within margin, no rotation bias, no opaque disk or background. This is a soft additive glow overlay, not a solid metal badge. No stars, glitter confetti, smoke or building. Preserve the original centered radial occupancy. Isolated alpha glow with zero background.''',
'spark':'''Target delivery91x87. ONE SMALL CENTERED honey-gold FOUR-POINT STAR GLINT, softly glowing. Bright warm-white tiny diamond core,4 smooth tapered short golden arms, gentle transparent honey-yellow outer halo. Occupy original centered silhouette footprint; center fixed at50%,50%. Very readable at50px display size. No cluster, no additional sparkles, no cloud, smoke, background, face or text. Simple premium cartoon completion sparkle, not a metallic badge.'''
}
for name,spec in specs.items():
    (REC/(name+'_prompt.txt')).write_text(common+'\n'+spec+'\n',encoding='utf-8')
(REC/'generation_jobs.json').write_text(json.dumps([dict(name=n,size='1536x576' if n=='saw' else '1152x896' if n=='hammer' else '1024x1024',prompt=n+'_prompt.txt') for n in specs],indent=2)+'\n',encoding='utf-8')
print('Prepared six image-specific edit prompts.')
